def _get_projection(self):
    """Get projection from the NetCDF4 attributes."""
    try:
        proj_str = self.nc.attrs["gdal_projection"]
    except TypeError:
        proj_str = self.nc.attrs["gdal_projection"].decode()

    height_scale = 1.0
    if "+h=1.000000" in proj_str:
        try:
            height = float(self.nc["projection_definition"].attrs["perspective_point_height"])
            height_scale = height
            proj_str = proj_str.replace("+h=1.000000", f"+h={height}")

            for param in ["+a=", "+b="]:
                if param in proj_str:
                    val_str = proj_str.split(param)[-1].split()[0]
                    val = float(val_str)
                    if val < 1.0:
                        proj_str = proj_str.replace(f"{param}{val_str}", f"{param}{val * height}")
        except (KeyError, TypeError):
            pass

    # Check the a/b/h units
    radius_a = proj_str.split("+a=")[-1].split()[0]
    if float(radius_a) > 10e3:
        units = "m"
        scale = 1.0
    else:
        units = "km"
        scale = 1e3

    if "units" not in proj_str:
        proj_str = proj_str + " +units=" + units

    area_extent = (float(self.nc.attrs["gdal_xgeo_up_left"]) * height_scale / scale,
                   float(self.nc.attrs["gdal_ygeo_low_right"]) * height_scale / scale,
                   float(self.nc.attrs["gdal_xgeo_low_right"]) * height_scale / scale,
